const body = input.body || input;
const errors = [];
if (!body.taskId) errors.push('taskId is required');
if (!body.propertyId) errors.push('propertyId is required');
if (!body.taskType) errors.push('taskType is required');
const validTypes = ['cleaning', 'maintenance', 'quality_check'];
if (body.taskType && !validTypes.includes(body.taskType)) errors.push('taskType must be cleaning|maintenance|quality_check');
if (!body.checkIn) errors.push('checkIn is required');
if (body.checkIn && isNaN(new Date(body.checkIn).getTime())) errors.push('checkIn must be a valid date');
return {
  taskId: body.taskId || null,
  propertyId: body.propertyId || null,
  bookingRef: body.bookingRef || null,
  taskType: body.taskType || null,
  status: body.status || 'NEW',
  agent: body.agent || null,
  checkIn: body.checkIn || null,
  vipGuest: body.vipGuest === true,
  incidentReported: body.incidentReported === true,
  incidentDetail: body.incidentDetail || '',
  qcStatus: body.qcStatus || 'pending',
  notes: body.notes || '',
  valid: errors.length === 0,
  errors: errors
};

return {
  _action: 'REJECTED',
  taskId: input.taskId,
  propertyId: input.propertyId,
  valid: false,
  errors: input.errors,
  status: 'BLOCKED - invalid CleanStay task',
  createdAt: new Date().toISOString()
};

const s = String(input.status || 'NEW').toUpperCase();
const status = (s === 'IN_PROGRESS' || s === 'COMPLETED') ? s : 'NEW';
return { ...input, status: status, normalizedAt: new Date().toISOString() };

const now = Date.now();
const checkIn = new Date(input.checkIn).getTime();
const hoursLeft = (checkIn - now) / 3600000;
const slaBreach = checkIn < now;
let score = 0;
if (input.vipGuest) score += 50;
if (hoursLeft <= 3) score += 40;
else if (hoursLeft <= 8) score += 20;
if (input.taskType === 'maintenance') score += 15;
if (slaBreach) score += 30;
if (input.status === 'COMPLETED') score = 0;
const priority = score >= 50 ? 'high' : (score >= 25 ? 'medium' : 'low');
let riskLevel = 'ready';
if (input.status !== 'COMPLETED' && (slaBreach || score >= 50)) riskLevel = 'not_ready';
else if (input.status !== 'COMPLETED' && score >= 25) riskLevel = 'at_risk';
return {
  ...input,
  priorityScore: score,
  priority: priority,
  riskLevel: riskLevel,
  slaBreach: slaBreach,
  hoursLeft: Math.round(hoursLeft * 10) / 10
};

const roster = [
  { name: 'Sara', activeTasks: 2, available: true },
  { name: 'Omar', activeTasks: 5, available: true },
  { name: 'Yasmine', activeTasks: 1, available: true },
  { name: 'Mehdi', activeTasks: 3, available: true }
];
let assigned = input.agent || null;
if (!assigned && input.status !== 'COMPLETED') {
  const free = roster.filter(r => r.available).sort((a, b) => a.activeTasks - b.activeTasks);
  assigned = free.length > 0 ? free[0].name : null;
}
return {
  ...input,
  assignedAgent: assigned,
  assignmentMode: input.agent ? 'kept' : 'auto',
  assignedAt: new Date().toISOString()
};

const t = input.body || input;
const fields = {
  TaskId: t.taskId || '',
  Property: t.propertyId || '',
  Booking: t.bookingRef || '',
  Type: t.taskType || '',
  Status: t.status || 'NEW',
  Priority: t.priority || 'low',
  Risk: t.riskLevel || 'ready',
  Agent: t.assignedAgent || t.agent || '',
  Notes: t.notes || '',
  Channel: 'escalation',
  ReceivedAt: new Date().toISOString()
};
if (t.checkIn) fields.CheckIn = t.checkIn;
return { records: [{ fields: fields }] };

const t = input.body || input;
const fields = {
  TaskId: t.taskId || '',
  Property: t.propertyId || '',
  Booking: t.bookingRef || '',
  Type: t.taskType || '',
  Status: t.status || 'NEW',
  Priority: t.priority || 'low',
  Risk: t.riskLevel || 'ready',
  Agent: t.assignedAgent || t.agent || '',
  Notes: t.notes || '',
  Channel: 'team',
  ReceivedAt: new Date().toISOString()
};
if (t.checkIn) fields.CheckIn = t.checkIn;
return { records: [{ fields: fields }] };

const recs = (input.body && input.body.records) || input.records || [];
const tasks = recs
  .map((rec) => {
    const f = rec.fields || {};
    return {
      taskId: f.TaskId || '',
      propertyId: f.Property || '',
      bookingRef: f.Booking || '',
      taskType: f.Type || '',
      status: f.Status || 'NEW',
      priority: f.Priority || 'low',
      riskLevel: f.Risk || 'ready',
      assignedAgent: f.Agent || '',
      checkIn: f.CheckIn || '',
      channel: f.Channel || ''
    };
  })
  .filter((t) => t.status !== 'COMPLETED');
const critical = tasks.filter((t) => t.riskLevel === 'not_ready' || t.priority === 'high');
return {
  openCount: tasks.length,
  criticalCount: critical.length,
  openTasks: tasks,
  criticalTasks: critical,
  generatedAt: new Date().toISOString()
};
